Definition PRIVSIG_STACK : Z := 80.

Definition privsig_post (ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (C clk lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (C, C + 48)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ PCond m' C clk
    /\ CanaryReads m'.

Definition privsig_stmt_at (pc : Z) (STK : Z) : Prop :=
  forall (C clk lo : Z) ra sp gp tp t0 t1 t2 s0 s1 (n : word) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  PCond m C clk ->
  (C + 48 <= 0x10000 \/ 0xb8000 <= C) ->
  bv_unsigned n <> 0 ->
  CanaryReads m ->
  stk usegs m lo (bv_unsigned sp) -> lo + STK <= bv_unsigned sp -> hceil <= lo ->
  (C + 48 <= lo \/ bv_unsigned sp <= C) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (privsig_post ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc C clk lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) n a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom usegs)).

Definition privsig_stmt : Prop := privsig_stmt_at P_PRIVATE_COND_SIGNAL PRIVSIG_STACK.

